SELECT COUNT(1) FROM grant_table gt INNER JOIN sys_role r ON r.id = gt.role_id WHERE gt.subject_type = #{subjectType} AND gt.subject_id = #{subjectId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}

SELECT r.id, r.role_code, r.role_name, r.status FROM grant_table gt INNER JOIN sys_role r ON r.id = gt.role_id WHERE gt.subject_type = #{subjectType} AND gt.subject_id = #{subjectId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}
ORDER BY r.role_code
